//json-schema.org/draft/2020-12/schema","$id":"https://github.com/vassiliylakhonin/agenda-intelligence-md/schemas/v1/middle-corridor-deal-risk-request.schema.json","title":"MiddleCorridorDealRiskRequest","description":"Product-grade structured request contract for Kazakhstan / Middle Corridor deal-risk evidence triage. This schema describes caller-supplied route, cargo, counterparty, dated-source, and decision-stage inputs. It does not enable live retrieval, factual-truth verification, legal advice, sanctions advice, compliance advice, financial advice, investment advice, insurance advice, or trading advice.","x-schema-version":"1","type":"object","additionalProperties":false,"required":["route","cargo","counterparties","dated_sources","risk_question","decision_stage"],"properties":{"route":{"type":"string","minLength":1,"description":"Route, corridor, or transit path under review."},"cargo":{"type":"string","minLength":1,"description":"Cargo, commodity, goods, or shipment type under review."},"shipment_value":{"type":"object","additionalProperties":false,"required":["amount","currency"],"properties":{"amount":{"type":"number","minimum":0},"currency":{"type":"string","enum":["USD","EUR","GBP","KZT","CNY","TRY","AED","other"]}}},"counterparties":{"type":"array","minItems":1,"items":{"$ref":"#/$defs/counterparty"}},"dated_sources":{"type":"array","items":{"$ref":"#/$defs/dated_source"}},"risk_question":{"type":"string","minLength":1},"decision_stage":{"type":"string","enum":["pre_signature","pre_shipment","in_transit","post_incident","committee_review","other"]},"notes":{"type":"string","minLength":1},"requested_output":{"type":"string","enum":["structured_json","markdown_summary","both"],"default":"structured_json"}},"$defs":{"counterparty":{"type":"object","additionalProperties":false,"required":["role","name"],"properties":{"role":{"type":"string","enum":["shipper","forwarder","carrier","port_agent","consignee","bank","insurer","broker","customs_broker","unknown","other"]},"name":{"type":"string","minLength":1},"jurisdiction":{"type":"string","minLength":1},"notes":{"type":"string","minLength":1},"specified_sectors":{"type":"array","description":"Optional. Sectors the counterparty operates in, drawn from OFAC FAQ 1148 / 1151 named sectors of the Russian Federation economy. A counterparty operating in any non-'other' value carries automatic FFI sanctions-exposure context under EO 14024 as amended by EO 14114. Structural tagging only; not a sanctions determination.","items":{"type":"string","enum":["technology","defense_and_related_materiel","construction","aerospace","manufacturing","other"]}},"date_of_formation":{"type":"string","format":"date","description":"Optional. ISO 8601 date of the counterparty's company formation. Drawn from the OFAC FFI advisory red-flag pattern of a newly-formed entity in a transshipment-risk jurisdiction. Structural tagging only; not a sanctions determination."}}},"dated_source":{"type":"object","additionalProperties":false,"required":["id","source_type","title","date"],"properties":{"id":{"type":"string","minLength":1},"source_type":{"$ref":"#/$defs/source_type"},"title":{"type":"string","minLength":1},"date":{"type":"string","format":"date"},"url":{"type":"string","format":"uri"},"notes":{"type":"string","minLength":1}}},"source_type":{"type":"string","enum":["port_operator_notice","sanctions_list_extract","carrier_note","counterparty_registry_extract","beneficial_ownership_source","customs_or_regulatory_source","insurance_clause_or_underwriter_note","vessel_or_carrier_history","rail_capacity_or_border_wait_source","contract_or_invoice_extract","end_user_or_reexport_evidence","source_of_funds_or_wealth_evidence","pep_screening_evidence","business_substance_evidence","user_provided_note","other"]}},"examples":[{"route":"Altynkol -> Aktau/Kuryk -> Baku -> Poti","cargo":"industrial equipment","shipment_value":{"amount":2400000,"currency":"USD"},"counterparties":[{"role":"forwarder","name":"Kazakhstan forwarder","jurisdiction":"Kazakhstan"}],"dated_sources":[{"id":"e1","source_type":"port_operator_notice","title":"Port operator notice","date":"2026-05-20","url":"https://example.com/port-notice"}],"risk_question":"Should this be escalated before contract signature?","decision_stage":"pre_signature","requested_output":"structured_json"}]},"schemas/v1/middle-corridor-deal-risk-response.schema.json":{"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://github.com/vassiliylakhonin/agenda-intelligence-md/schemas/v1/middle-corridor-deal-risk-response.schema.json","title":"MiddleCorridorDealRiskResponse","description":"Product-grade structured response contract for Kazakhstan / Middle Corridor deal-risk evidence triage. This schema supports source-coverage gaps, escalation routing, watch-next indicators, and human-review requirements. It does not provide legal advice, sanctions advice, compliance advice, financial advice, investment advice, insurance advice, trading advice, live retrieval, or factual-truth verification.","x-schema-version":"1","type":"object","additionalProperties":false,"required":["triage_recommendation","risk_signal","decision_readiness_score","decision_readiness_label","supplied_sources","minimum_sources_before_go","evidence_gaps","watch_next","human_review_required","not_advice_notice"],"properties":{"triage_recommendation":{"type":"string","enum":["not_decision_ready","escalate_before_signature","escalate_before_shipment","ready_for_human_review","insufficient_information"]},"risk_signal":{"type":"string","enum":["low","medium","medium_high","high","unknown"]},"decision_readiness_score":{"description":"Heuristic 0-100 score for evidence-pack readiness for human review. This is not approval, clearance, legal advice, sanctions advice, compliance advice, financial advice, investment advice, insurance advice, or trading advice.","type":"integer","minimum":0,"maximum":100},"decision_readiness_label":{"type":"string","enum":["insufficient_information","not_decision_ready","partial","review_ready"]},"link_integrity":{"description":"Observe-only structural lint of cited source-URL well-formedness. Present only when at least one supplied source carries a malformed or placeholder URL. Structural check only: it does not fetch URLs, verify that a page exists, perform live retrieval, or verify factual content. It does not change the triage recommendation, risk signal, operational decision, or evidence gaps.","type":"object","additionalProperties":false,"required":["checked","flagged"],"properties":{"checked":{"type":"integer","minimum":0},"well_formed":{"type":"integer","minimum":0},"illustrative":{"type":"integer","minimum":0},"flagged":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["url","reason"],"properties":{"source_id":{"type":"string"},"source_type":{"type":"string"},"url":{"type":"string"},"reason":{"type":"string"}}}}}},"operational_decision":{"description":"Logistics/ops-facing booking decision derived from the decision-readiness score, risk signal, triage recommendation, and decision stage. Triage routing only; not clearance, approval, a sanctions determination, or any legal, sanctions, compliance, financial, investment, insurance, or trading advice. It never issues a hard reject (a compliance/legal call) and stops at hold or escalate. Human review is required before any commercial action.","type":"object","additionalProperties":false,"required":["decision","applies_to","rationale"],"properties":{"decision":{"type":"string","enum":["proceed","proceed_with_conditions","hold","escalate"]},"applies_to":{"type":"string","minLength":1},"rationale":{"type":"string","minLength":1}}},"route":{"type":"string","minLength":1},"cargo":{"type":"string","minLength":1},"shipment_value":{"type":"object","additionalProperties":false,"required":["amount","currency"],"properties":{"amount":{"type":"number","minimum":0},"currency":{"type":"string","enum":["USD","EUR","GBP","KZT","CNY","TRY","AED","other"]}}},"counterparties":{"type":"array","items":{"$ref":"#/$defs/counterparty"}},"supplied_sources":{"type":"array","items":{"$ref":"#/$defs/source_type"}},"minimum_sources_before_go":{"type":"array","items":{"$ref":"#/$defs/source_type"}},"evidence_gaps":{"type":"array","items":{"type":"string","minLength":1}},"top_risks":{"type":"array","items":{"type":"string","minLength":1}},"exposure_layers":{"type":"object","additionalProperties":false,"description":"Risk picture decomposed into the two layers a practitioner separates: home-jurisdiction legal / documentation posture (not assessed by this product) versus foreign / secondary-sanctions exposure. Structural decomposition only; not a legal or sanctions determination.","properties":{"domestic_legal_layer":{"type":"array","items":{"type":"string","minLength":1}},"foreign_sanctions_exposure_layer":{"type":"array","items":{"type":"string","minLength":1}}}},"vessel_due_diligence_indicators":{"type":"array","description":"Deceptive-shipping-practice (DSP) verification checklist surfaced for the maritime leg when vessel / carrier history is not yet supplied. An evidence-gap checklist routed to human review (drawn from OFAC maritime guidance); not vessel adjudication, AIS analysis, live retrieval, or insurance advice.","items":{"type":"string","minLength":1}},"reexport_control_indicators":{"type":"array","description":"End-use / end-user verification checklist surfaced when end-user or no-re-export evidence is not yet supplied. An evidence-gap checklist routed to human review (drawn from EU Sanctions Helpdesk and US end-user diversion red flags); not an end-use determination, sanctions determination, live retrieval, or legal advice. Does not affect the decision-readiness score.","items":{"type":"string","minLength":1}},"source_of_funds_indicators":{"type":"array","description":"Source-of-funds / source-of-wealth verification checklist surfaced when source-of-funds-or-wealth evidence is not yet supplied. An evidence-gap checklist routed to human review (drawn from FATF Recommendation 10 EDD guidance); not a financial determination, AML clearance, live retrieval, or financial advice. Does not affect the decision-readiness score.","items":{"type":"string","minLength":1}},"pep_screening_indicators":{"type":"array","description":"Politically-exposed-person (PEP) screening checklist surfaced when PEP-screening evidence is not yet supplied. An evidence-gap checklist routed to human review (drawn from FATF Recommendations 12 and 22); not a PEP determination, a political-exposure judgment, live retrieval, or legal advice. Does not affect the decision-readiness score.","items":{"type":"string","minLength":1}},"front_company_indicators":{"type":"array","description":"Front-company / business-substance checklist surfaced when business-substance evidence is not yet supplied. An evidence-gap checklist routed to human review (drawn from EU Sanctions Helpdesk counterparty red flags: recently established or no business background, little or no web presence, shared addresses, line-of-business mismatch, contact only via broad power of attorney); not a shell-company determination, an ownership determination, live retrieval, or legal advice. Does not affect the decision-readiness score.","items":{"type":"string","minLength":1}},"route_sanctions_exposure_indicators":{"type":"array","description":"Standing route-screening checklist of Middle Corridor connections that carry elevated sanctions-program exposure: Iran-transit legs and Russia Northern Corridor overlaps (OFAC Iran and Russia programs), sanctioned Caspian operators, and onward connections into a sanctions-relevant jurisdiction. Presence-flagging routed to human review; not a sanctions determination, live screening, or legal advice.","items":{"type":"string","minLength":1}},"route_sanctions_matched_segments":{"type":"array","description":"Corridor segments named in the declared route text that match a sanctions-exposed 